import * as THREE from 'three'
import {
  carpetTexture,
  emblemTexture,
  goldMarbleTexture,
  rouletteTexture,
  signTexture,
  slotScreenTexture,
  sunburstTexture,
  wallMarbleTexture,
  woodTexture,
} from './textures'

export type InteractableKind = 'slot' | 'blackjack' | 'roulette' | 'bar'

export type Interactable = {
  id: string
  kind: InteractableKind
  label: string
  detail: string
  position: THREE.Vector3
  radius: number
  variant?: 'high'
}

export type BoxCollider = {
  shape: 'box'
  minX: number
  maxX: number
  minZ: number
  maxZ: number
  enabled: boolean
}

export type CircleCollider = {
  shape: 'circle'
  x: number
  z: number
  radius: number
  enabled: boolean
}

export type Collider = BoxCollider | CircleCollider

export type CasinoWorld = {
  scene: THREE.Scene
  interactables: Interactable[]
  colliders: Collider[]
  update: (elapsed: number, delta: number, player: THREE.Vector3) => void
}

function box(
  parent: THREE.Object3D,
  width: number,
  height: number,
  depth: number,
  material: THREE.Material,
  x: number,
  y: number,
  z: number,
  shadows = true,
) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(width, height, depth), material)
  mesh.position.set(x, y, z)
  mesh.castShadow = shadows
  mesh.receiveShadow = shadows
  parent.add(mesh)
  return mesh
}

function cylinder(
  parent: THREE.Object3D,
  radiusTop: number,
  radiusBottom: number,
  height: number,
  segments: number,
  material: THREE.Material,
  x: number,
  y: number,
  z: number,
  shadows = true,
) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radiusTop, radiusBottom, height, segments), material)
  mesh.position.set(x, y, z)
  mesh.castShadow = shadows
  mesh.receiveShadow = shadows
  parent.add(mesh)
  return mesh
}

function plane(
  parent: THREE.Object3D,
  width: number,
  height: number,
  material: THREE.Material,
  x: number,
  y: number,
  z: number,
  rotationY = 0,
  rotationX = 0,
) {
  const mesh = new THREE.Mesh(new THREE.PlaneGeometry(width, height), material)
  mesh.position.set(x, y, z)
  mesh.rotation.set(rotationX, rotationY, 0)
  mesh.receiveShadow = true
  parent.add(mesh)
  return mesh
}

function addPointLight(
  parent: THREE.Object3D,
  color: number,
  intensity: number,
  distance: number,
  x: number,
  y: number,
  z: number,
  decay = 2,
) {
  const light = new THREE.PointLight(color, intensity, distance, decay)
  light.position.set(x, y, z)
  parent.add(light)
  return light
}

function makeSign(
  parent: THREE.Object3D,
  text: string,
  width: number,
  height: number,
  x: number,
  y: number,
  z: number,
  rotationY = 0,
  color?: string,
  glow?: string,
) {
  const texture = signTexture(text, {
    width: 1024,
    height: Math.max(180, Math.round((1024 * height) / width)),
    color,
    glow,
    size: Math.round((Math.max(180, (1024 * height) / width)) * 0.52),
  })
  const material = new THREE.MeshBasicMaterial({
    map: texture,
    transparent: true,
    depthWrite: false,
    toneMapped: false,
    side: THREE.DoubleSide,
  })
  const mesh = plane(parent, width, height, material, x, y, z, rotationY)
  mesh.renderOrder = 3
  return mesh
}

function makeFrame(
  parent: THREE.Object3D,
  width: number,
  height: number,
  x: number,
  y: number,
  z: number,
  rotationY: number,
  goldMaterial: THREE.Material,
  wallMaterial: THREE.Material,
) {
  const group = new THREE.Group()
  group.position.set(x, y, z)
  group.rotation.y = rotationY
  parent.add(group)
  box(group, width, height, 0.08, wallMaterial, 0, 0, 0)
  box(group, width + 0.18, 0.14, 0.14, goldMaterial, 0, height / 2 + 0.03, 0.03)
  box(group, width + 0.18, 0.14, 0.14, goldMaterial, 0, -height / 2 - 0.03, 0.03)
  box(group, 0.14, height + 0.18, 0.14, goldMaterial, -width / 2 - 0.03, 0, 0.03)
  box(group, 0.14, height + 0.18, 0.14, goldMaterial, width / 2 + 0.03, 0, 0.03)
  return group
}

export function createCasinoWorld(): CasinoWorld {
  const scene = new THREE.Scene()
  scene.background = new THREE.Color(0x080603)
  scene.fog = new THREE.FogExp2(0x0b0703, 0.016)

  const interactables: Interactable[] = []
  const colliders: Collider[] = []

  const goldTexture = goldMarbleTexture()
  const wallTexture = wallMarbleTexture()
  const wood = woodTexture()
  const carpet = carpetTexture()
  const sunburst = sunburstTexture()
  const emblem = emblemTexture()
  const slotFace = slotScreenTexture()
  const rouletteFace = rouletteTexture()

  const gold = new THREE.MeshStandardMaterial({
    color: 0xd8b04a,
    metalness: 0.95,
    roughness: 0.24,
    envMapIntensity: 1.45,
  })
  const paleGold = new THREE.MeshStandardMaterial({
    color: 0xf4d77c,
    metalness: 0.88,
    roughness: 0.2,
    emissive: 0x3a2500,
    emissiveIntensity: 0.35,
    envMapIntensity: 1.5,
  })
  const agedGold = new THREE.MeshStandardMaterial({
    color: 0x8a641d,
    metalness: 0.85,
    roughness: 0.38,
    envMapIntensity: 1.1,
  })
  const darkMetal = new THREE.MeshStandardMaterial({
    color: 0x17130d,
    metalness: 0.8,
    roughness: 0.34,
    envMapIntensity: 0.7,
  })
  const wall = new THREE.MeshStandardMaterial({
    map: wallTexture,
    color: 0x8b7042,
    roughness: 0.58,
    metalness: 0.18,
    envMapIntensity: 0.7,
  })
  const darkWall = new THREE.MeshStandardMaterial({
    map: wallTexture,
    color: 0x3c2c17,
    roughness: 0.7,
    metalness: 0.12,
    envMapIntensity: 0.5,
  })
  const floor = new THREE.MeshPhysicalMaterial({
    map: goldTexture,
    color: 0xffdf95,
    metalness: 0.62,
    roughness: 0.19,
    clearcoat: 0.8,
    clearcoatRoughness: 0.13,
    envMapIntensity: 1.25,
  })
  const felt = new THREE.MeshStandardMaterial({
    color: 0x075332,
    roughness: 0.94,
    metalness: 0.02,
  })
  const velvet = new THREE.MeshStandardMaterial({
    color: 0x4e0711,
    roughness: 0.98,
    metalness: 0.02,
  })
  const woodMaterial = new THREE.MeshStandardMaterial({
    map: wood,
    color: 0xb07940,
    roughness: 0.46,
    metalness: 0.18,
    envMapIntensity: 0.8,
  })
  const ceiling = new THREE.MeshStandardMaterial({
    color: 0x0d0b08,
    roughness: 0.88,
    metalness: 0.14,
  })
  const warmLight = new THREE.MeshBasicMaterial({
    color: 0xffd98a,
    toneMapped: false,
  })
  const water = new THREE.MeshPhysicalMaterial({
    color: 0x2b9fa2,
    metalness: 0.15,
    roughness: 0.06,
    transparent: true,
    opacity: 0.72,
    envMapIntensity: 2.1,
    clearcoat: 1,
  })

  // ── Architecture ────────────────────────────────────────────────────────
  const lobbyFloor = new THREE.Mesh(new THREE.PlaneGeometry(34, 30), floor)
  lobbyFloor.rotation.x = -Math.PI / 2
  lobbyFloor.receiveShadow = true
  scene.add(lobbyFloor)

  const rearFloor = new THREE.Mesh(new THREE.PlaneGeometry(14, 12), floor)
  rearFloor.rotation.x = -Math.PI / 2
  rearFloor.position.set(0, 0, -21)
