  }

  .logo-sub {
    margin-top: 14px;
    letter-spacing: 0.44em;
    text-indent: 0.44em;
  }

  .start-tagline {
    margin-top: 22px;
    font-size: 13px;
  }

  .start-button {
    margin-top: 28px;
    padding: 17px 22px;
    font-size: 14px;
  }

  .start-hint {
    font-size: 8px;
    line-height: 1.7;
  }

  .start-crest {
    margin-bottom: 13px;
  }

  .pause-panel {
    padding: 36px 24px 30px;
  }

  .pause-panel h2 {
    font-size: 40px;
  }

  .slot-cabinet {
    padding: 14px;
  }

  .slot-marquee {
