  }

  .slot-controls {
    grid-template-columns: 1fr;
  }

  .slot-controls .spin-button {
    grid-row: 1;
    width: 100%;
  }

  .game-panel {
    overflow: auto;
  }

  .blackjack-table {
    padding: 26px 18px 18px;
  }

  .blackjack-controls,
  .roulette-controls {
    padding: 22px 18px;
  }
