  left: max(24px, env(safe-area-inset-left));
  width: 112px;
  height: 112px;
  border: 1px solid rgba(212, 175, 55, 0.3);
  border-radius: 50%;
  background: rgba(8, 6, 2, 0.28);
  backdrop-filter: blur(4px);
  pointer-events: auto;
  touch-action: none;
}

.touch-stick-ring {
  position: absolute;
  inset: 16px;
  border: 1px dashed rgba(212, 175, 55, 0.2);
  border-radius: 50%;
}

.touch-stick-knob {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 44px;
  height: 44px;
  transform: translate(-50%, -50%);
  border: 1px solid rgba(245, 211, 116, 0.7);
  border-radius: 50%;
  background: rgba(61, 45, 8, 0.7);
  box-shadow: 0 0 18px rgba(212, 175, 55, 0.18);
}

.touch-interact,
.touch-sprint {
  position: fixed;
  display: grid;
  place-items: center;
  width: 62px;
  height: 62px;
  border: 1px solid rgba(245, 211, 116, 0.7);
  border-radius: 50%;
  background: rgba(30, 22, 5, 0.6);
  color: #ffe6a1;
  font-family: var(--serif);
  font-size: 22px;
  pointer-events: auto;
  backdrop-filter: blur(4px);
}

.touch-interact {
  right: max(28px, env(safe-area-inset-right));
  bottom: max(36px, env(safe-area-inset-bottom));

